#[test]
fn test_lambert_wm1f_at_random_values() {
    for (x, expected) in WM1F_RANDOM_ANSWERS {
        println!("{} at {x}", ulp_err32(lambert_wm1f(x), expected));
        assert_only_ulps_eq!(lambert_wm1f(x), expected, max_ulps = WF_MAX_ULPS);
    }
}
